(function(){function getCustomMessage(){const jurisdiction=window.Osano?.cm?.jurisdiction;const locale=window.Osano?.cm?.locale;const baseUrl=(window.sbOsanoConfig&&window.sbOsanoConfig.baseUrl)?window.sbOsanoConfig.baseUrl.replace(/\/$/,''):'';if(!locale||!String(locale).startsWith('en'))return null;const privacyChoicesLink='<a href="'+baseUrl+'/online-consumer-request-form/">privacy choices</a>';if(jurisdiction==='us-ca'||(jurisdiction&&jurisdiction.startsWith('us-ca'))){return'Subject to your '+privacyChoicesLink+', we and our third-party partners use cookies and similar technologies to view and retain your site interactions, to perform analytics, improve user experience, enable site functionality, and assist our marketing efforts. By continuing to use our site, you consent to these data practices. See our <a href="'+baseUrl+'/privacy-policy/">Privacy Policy</a> and <a href="'+baseUrl+'/privacy-policy/#onlineconsumerrequest">California Notice At Collection</a> for more details.';}
if(jurisdiction==='ca'||(jurisdiction&&jurisdiction.startsWith('ca-'))||jurisdiction==='sg'||(jurisdiction&&jurisdiction.startsWith('sg-'))){return'Subject to your '+privacyChoicesLink+', we and our third-party partners use cookies and similar technologies to view and retain your site interactions, to perform analytics, improve user experience, enable site functionality, and assist our marketing efforts. By continuing to use our site, you consent to these data practices. See our <a href="'+baseUrl+'/privacy-policy/">Privacy Policy</a> for more details.';}
if(jurisdiction==='hk'||(jurisdiction&&jurisdiction.startsWith('hk-'))){return'Subject to your '+privacyChoicesLink+', we and our third-party partners use cookies and similar technologies to view and retain your site interactions, to perform analytics, improve user experience, enable site functionality, and assist our marketing efforts. By continuing to use our site, you consent to these data practices. See our <a href="'+baseUrl+'/privacy-policy/">Privacy Policy</a> and <a href="'+baseUrl+'/privacy-policy/pics/">Personal Information Collection Statement</a> for more details.';}
return null;}
function applyMessage(messageHtml){const bannerRoot=document.querySelector('.osano-cm-window');if(!bannerRoot)return false;const messageEl=bannerRoot.querySelector('.osano-cm-content__message')||bannerRoot.querySelector('.osano-cm-message')||bannerRoot.querySelector('[data-qa="osano-cm-message"]');if(!messageEl)return false;const policyLink=bannerRoot.querySelector('.osano-cm-storage-policy');if(policyLink)policyLink.style.display='none';if(messageEl.dataset.sbCustomApplied==='1')return true;messageEl.innerHTML=messageHtml;messageEl.dataset.sbCustomApplied='1';messageEl.querySelectorAll('a[href]').forEach((anchor)=>{anchor.style.color='#23527b';});messageEl.addEventListener('click',function(e){const link=e.target.closest('a[href]');if(!link)return;e.preventDefault();window.location.href=link.href;});return true;}
function start(){let attempts=0;const maxAttempts=40;const timer=setInterval(()=>{attempts++;const message=getCustomMessage();if(message&&applyMessage(message)){clearInterval(timer);}
if(attempts>=maxAttempts){clearInterval(timer);}},250);}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',start,{once:true});}else{start();}})();